import { RegistrationError } from '../kernel/errors.js'; export class SearchIndex { #docs=new Map(); upsert({id,domain,title,text,sensitivity='private',permission='read',provenance}){if(!id||!domain||!title||!provenance)throw new RegistrationError('Search document requires id, domain, title, provenance');const doc=Object.freeze({id,domain,title,text:String(text??''),sensitivity,permission,provenance:structuredClone(provenance)});this.#docs.set(id,doc);return doc;} query(term,{permissions=[]}={}){const q=String(term??'').trim().toLowerCase();if(!q)return Object.freeze([]);return Object.freeze([...this.#docs.values()].filter(doc=>permissions.includes(doc.permission)&&(`${doc.title} ${doc.text}`).toLowerCase().includes(q)));}}
